<form method="POST" action="{{ $releaseNote ? route('saas-ops.release-notes.update',$releaseNote) : route('saas-ops.release-notes.store') }}" class="rounded-xl border bg-white p-5 dark:border-slate-800 dark:bg-slate-900">@csrf @if($releaseNote) @method('PUT') @endif<div class="grid gap-4 md:grid-cols-2"><input name="version" value="{{ old('version',$releaseNote?->version) }}" placeholder="version" class="rounded-lg dark:bg-slate-950"><input name="title" value="{{ old('title',$releaseNote?->title) }}" placeholder="title" class="rounded-lg dark:bg-slate-950"><select name="status" class="rounded-lg dark:bg-slate-950"><option value="draft" @selected(old('status',$releaseNote?->status ?? 'draft')==='draft')>draft</option><option value="published" @selected(old('status',$releaseNote?->status)==='published')>published</option></select></div><textarea name="summary" class="mt-3 w-full rounded-lg dark:bg-slate-950" placeholder="summary">{{ old('summary',$releaseNote?->summary) }}</textarea><textarea name="body" class="mt-3 w-full rounded-lg dark:bg-slate-950" placeholder="body">{{ old('body',$releaseNote?->body) }}</textarea><button class="mt-3 rounded-lg bg-lime-500 px-4 py-2 text-sm font-black text-white">Simpan</button></form>
